function base64ToArrayBuffer(base64) {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

function resolveReelLanguage(info) {
  if (info && info.lang && info.lang !== "auto") return info.lang;
  if (typeof cfg !== "undefined" && cfg.reelLang && cfg.reelLang !== "auto") return cfg.reelLang;
  if (typeof cfg !== "undefined") {
    if (cfg.voiceAppreciationLang && cfg.voiceAppreciationLang !== "auto") return cfg.voiceAppreciationLang;
    if (cfg.breathLang) return cfg.breathLang;
    if (cfg.pranaLang) return cfg.pranaLang;
    if (cfg.quoteLang) return cfg.quoteLang;
  }
  return "mr"; // Default to Marathi
}

function loadReelAssetImage(src) {
  return new Promise((resolve) => {
    const img = new Image();
    if (typeof window !== "undefined" && window.location && window.location.protocol !== "file:") {
      img.crossOrigin = "anonymous";
    }
    img.onload = () => resolve(img);
    img.onerror = () => {
      console.warn("[Reel Generator] Asset image load fallback:", src);
      resolve(null);
    };
    img.src = src;
  });
}

function drawRoundedCard(ctx, x, y, w, h, r, fill, stroke, lw) {
  ctx.save();
  ctx.beginPath();
  if (ctx.roundRect) {
    ctx.roundRect(x, y, w, h, r);
  } else {
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }
  if (fill) {
    ctx.fillStyle = fill;
    ctx.fill();
  }
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw || 2;
    ctx.stroke();
  }
  ctx.restore();
}

function drawGlowText(ctx, text, x, y, font, color, glowCol, glowBlur, align) {
  ctx.save();
  ctx.font = font;
  ctx.fillStyle = color;
  ctx.textAlign = align || "center";
  ctx.textBaseline = "middle";
  if (glowCol) {
    ctx.shadowColor = glowCol;
    ctx.shadowBlur = glowBlur || 12;
  }
  ctx.fillText(text, x, y);
  ctx.restore();
}

