// ── Scene 1: Bhagavad Gita 2.47 (0.0s – 10.0s | 10s) ──
function drawScene1_Gita(ctx, t, lang) {
  const L = REEL_I18N[lang] || REEL_I18N.mr;
  drawRoundedCard(ctx, 150, 42, 420, 46, 23, "rgba(12, 18, 38, 0.88)", "rgba(245, 158, 11, 0.65)", 2);
  drawGlowText(ctx, L.topBrand, 360, 65, "bold 16px sans-serif", "#FDE047", "rgba(245, 158, 11, 0.5)", 8);

  drawRoundedCard(ctx, 40, 108, 640, 160, 20, "rgba(12, 18, 38, 0.90)", "rgba(245, 158, 11, 0.6)", 2);
  drawGlowText(ctx, L.gitaHeader, 360, 140, "bold 16px sans-serif", "#FCD34D", null, 0);
  
  const fShloka = lang === "en" ? "bold 20px 'Cinzel', serif" : "bold 23px 'Noto Serif Devanagari', serif";
  drawGlowText(ctx, L.gitaLine1, 360, 182, fShloka, "#FFFBEB", "rgba(255, 215, 0, 0.6)", 10);
  drawGlowText(ctx, L.gitaLine2, 360, 225, fShloka, "#FFFBEB", "rgba(255, 215, 0, 0.6)", 10);

  if (t >= 2.5) {
    const animAlpha = Math.min(1.0, (t - 2.5) * 2.0);
    ctx.save();
    ctx.globalAlpha = animAlpha;
    drawRoundedCard(ctx, 40, 288, 640, 145, 20, "rgba(15, 23, 48, 0.92)", "rgba(251, 191, 36, 0.5)", 2);
    drawGlowText(ctx, L.meaningHeader, 360, 318, "bold 15px sans-serif", "#FCD34D", null, 0);
    drawGlowText(ctx, L.meaningLine1, 360, 355, "bold 18px sans-serif", "#FEF3C7", null, 0);
    drawGlowText(ctx, L.meaningLine2, 360, 392, "bold 18px sans-serif", "#FEF3C7", null, 0);
    ctx.restore();
  }

  drawRoundedCard(ctx, 110, 1190, 500, 48, 24, "rgba(245, 158, 11, 0.22)", "rgba(245, 158, 11, 0.6)", 2);
  drawGlowText(ctx, L.sadhanaPill, 360, 1214, "bold 17px sans-serif", "#FEF08A", "rgba(245, 158, 11, 0.8)", 10);
}

// ── Scene 2: STANDARD 6-CARD FLANKING TABLE FORMAT (10.0s – 20.0s | 10s) ──
// Hanuman stands completely unblocked in the center channel!
function drawScene2_WorkoutReport(ctx, t, data, info, lang) {
  const L = REEL_I18N[lang] || REEL_I18N.mr;
  const sets = (info && info.todaySets) || (typeof todayDone === "function" ? todayDone() : 32);
  const total = (data && data.totalAllTime) || (info && info.totalSets) || 1024;
  const streak = (data && data.streak) || (info && info.streakDays) || 14;
  const userW = (typeof cfg !== "undefined" && cfg.userWeight) ? cfg.userWeight : 68;
  const cal = (info && info.calories) || Math.round((8.0 * 3.5 * userW) / 200 * (sets * 1.0));
  const durStr = (info && info.durationStr) || (Math.floor(sets * 1.06) + (lang === "en" ? " mins" : " मि"));
  const waterStr = (userW * 0.035 + sets * 0.03).toFixed(1) + (lang === "en" ? " Liters" : " लिटर");
  const name = (info && info.name) || (typeof cfg !== "undefined" && cfg.userName) || (lang === "en" ? "Sadhak" : "साधक");

  const d = new Date();
  const monthsMr = ["जानेवारी", "फेब्रुवारी", "मार्च", "एप्रिल", "मे", "जून", "जुलै", "ऑगस्ट", "सप्टेंबर", "ऑक्टोबर", "नोव्हेंबर", "डिसेंबर"];
  const monthsEn = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const dateStr = lang === "en"
    ? `${monthsEn[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`
    : `${d.getDate()} ${monthsMr[d.getMonth()]} ${d.getFullYear()}`;

  // Top Header Card
  drawRoundedCard(ctx, 35, 38, 650, 72, 18, "rgba(12, 18, 38, 0.94)", "rgba(245, 158, 11, 0.8)", 2);
  drawGlowText(ctx, L.scoreHeader, 360, 62, "bold 19px sans-serif", "#FDE047", "rgba(245, 158, 11, 0.6)", 8);
  drawGlowText(ctx, `📅 ${dateStr}  ·  ${name}  ·  ${L.goalAchieved}`, 360, 90, "600 14px sans-serif", "#CBD5E1", null, 0);

  // LEFT COLUMN (x=24 to 226, w=202)
  // Left 1: Sets
  drawRoundedCard(ctx, 24, 155, 202, 95, 16, "rgba(15, 23, 42, 0.92)", "rgba(34, 211, 238, 0.8)", 2);
  drawGlowText(ctx, L.c1Title, 125, 178, "bold 15px sans-serif", "#F1F5F9", null, 0);
  drawGlowText(ctx, `${sets} / ${sets}`, 125, 206, "900 24px sans-serif", "#22D3EE", "rgba(34, 211, 238, 0.7)", 8);
  drawGlowText(ctx, L.c1Sub, 125, 232, "bold 12px sans-serif", "#67E8F9", null, 0);

  // Left 2: Time
  drawRoundedCard(ctx, 24, 270, 202, 95, 16, "rgba(15, 23, 42, 0.92)", "rgba(59, 130, 246, 0.8)", 2);
  drawGlowText(ctx, L.c2Title, 125, 293, "bold 15px sans-serif", "#F1F5F9", null, 0);
  drawGlowText(ctx, `${durStr} २० से`, 125, 321, "900 22px sans-serif", "#60A5FA", "rgba(59, 130, 246, 0.7)", 8);
  drawGlowText(ctx, L.c2Sub, 125, 347, "bold 12px sans-serif", "#93C5FD", null, 0);

  // Left 3: Calories
  drawRoundedCard(ctx, 24, 385, 202, 95, 16, "rgba(15, 23, 42, 0.92)", "rgba(249, 115, 22, 0.8)", 2);
  drawGlowText(ctx, L.c3Title, 125, 408, "bold 15px sans-serif", "#F1F5F9", null, 0);
  drawGlowText(ctx, `${cal} kcal`, 125, 436, "900 22px sans-serif", "#FB923C", "rgba(249, 115, 22, 0.7)", 8);
  drawGlowText(ctx, L.c3Sub, 125, 462, "bold 12px sans-serif", "#FDBA74", null, 0);

  // RIGHT COLUMN (x=494 to 696, w=202)
  // Right 1: Streak
  drawRoundedCard(ctx, 494, 155, 202, 95, 16, "rgba(15, 23, 42, 0.92)", "rgba(251, 191, 36, 0.8)", 2);
  drawGlowText(ctx, L.c4Title, 595, 178, "bold 15px sans-serif", "#F1F5F9", null, 0);
  drawGlowText(ctx, `${streak} ${lang === "en" ? "Days" : "दिवस"}`, 595, 206, "900 22px sans-serif", "#FCD34D", "rgba(251, 191, 36, 0.7)", 8);
  drawGlowText(ctx, L.c4Sub, 595, 232, "bold 12px sans-serif", "#FEF08A", null, 0);

  // Right 2: Total Sets
  drawRoundedCard(ctx, 494, 270, 202, 95, 16, "rgba(15, 23, 42, 0.92)", "rgba(192, 132, 252, 0.8)", 2);
  drawGlowText(ctx, L.c5Title, 595, 293, "bold 15px sans-serif", "#F1F5F9", null, 0);
  drawGlowText(ctx, `${total} ${lang === "en" ? "Sets" : "सेट्स"}`, 595, 321, "900 22px sans-serif", "#C084FC", "rgba(192, 132, 252, 0.7)", 8);
  drawGlowText(ctx, L.c5Sub, 595, 347, "bold 12px sans-serif", "#E9D5FF", null, 0);

  // Right 3: Hydration
  drawRoundedCard(ctx, 494, 385, 202, 95, 16, "rgba(15, 23, 42, 0.92)", "rgba(56, 189, 248, 0.8)", 2);
  drawGlowText(ctx, L.c6Title, 595, 408, "bold 15px sans-serif", "#F1F5F9", null, 0);
  drawGlowText(ctx, waterStr, 595, 436, "900 22px sans-serif", "#38BDF8", "rgba(56, 189, 248, 0.7)", 8);
  drawGlowText(ctx, L.c6Sub, 595, 462, "bold 12px sans-serif", "#BAE6FD", null, 0);

  // Bottom Banner
  drawRoundedCard(ctx, 45, 1180, 630, 56, 28, "rgba(245, 158, 11, 0.28)", "rgba(245, 158, 11, 0.8)", 2);
  drawGlowText(ctx, L.keepSadhana, 360, 1208, "bold 17px sans-serif", "#FEF08A", "rgba(245, 158, 11, 0.8)", 10);
}

